<template>
	<view class="container">
		<view class="title">职业档案设置</view>

		<view class="form-item">
			<text>专业</text>
			<input v-model="formData.major" placeholder="请输入专业" class="input" />
		</view>

		<view class="form-item">
			<text>年级</text>
			<input v-model="formData.grade" placeholder="如：大三" class="input" />
		</view>

		<view class="form-item">
			<text>学校</text>
			<input v-model="formData.school" placeholder="请输入学校" class="input" />
		</view>

		<button class="btn" @click="save">保存档案</button>
		<button class="btn btn-read" @click="read">读取档案</button>
		<button @click="uni.navigateTo({url: '/pages/career/jobs'})">去岗位列表</button>
	</view>
</template>

<script setup>
	
	import {
		ref,
		onMounted
	} from 'vue'

	const formData = ref({
		major: '',
		grade: '',
		school: ''
	})

	// 引入云对象
	const careerService = uniCloud.importObject('career-service')

	// 读取档案
	const read = async () => {
		uni.showLoading({
			title: '读取中...'
		})
		try {
			const res = await careerService.getProfile()
			if (res.code === 0 && res.data) {
				formData.value = {
					major: res.data.major,
					grade: res.data.grade,
					school: res.data.school
				}
				uni.showToast({
					title: '读取成功',
					icon: 'none'
				})
			} else {
				uni.showToast({
					title: '暂无档案',
					icon: 'none'
				})
			}
		} // 找到你的 catch 块，修改成类似这样：
		catch (e) {
			console.error('【读取档案】完整错误对象:', e) // 关键：打印完整的 e 对象
			uni.showToast({
				title: e.message || '读取失败',
				icon: 'none'
			}) // 页面提示也显示具体错误
			// 同时保留你原来的 console.error(e)
		}
		uni.hideLoading()
	}

	// 保存档案
	const save = async () => {
		if (!formData.value.major || !formData.value.grade) {
			return uni.showToast({
				title: '请填写专业和年级',
				icon: 'none'
			})
		}

		uni.showLoading({
			title: '保存中...'
		})
		try {
			const res = await careerService.saveProfile(formData.value)
			if (res.code === 0) {
				uni.showToast({
					title: '保存成功',
					icon: 'success'
				})
			} else {
				uni.showToast({
					title: res.message,
					icon: 'none'
				})
			}
		} // 找到你的 catch 块，修改成类似这样：
		catch (e) {
			console.error('【读取档案】完整错误对象:', e) // 关键：打印完整的 e 对象
			uni.showToast({
				title: e.message || '读取失败',
				icon: 'none'
			}) // 页面提示也显示具体错误
			// 同时保留你原来的 console.error(e)
		}
		uni.hideLoading()
	}

	// 页面加载时读取一次
	onMounted(() => {
		read()
	})
</script>

<style scoped>
	.container {
		padding: 20px;
	}

	.title {
		font-size: 20px;
		font-weight: bold;
		margin-bottom: 20px;
	}

	.form-item {
		margin-bottom: 15px;
	}

	.form-item text {
		display: block;
		margin-bottom: 5px;
		font-size: 14px;
		color: #333;
	}

	.input {
		border: 1px solid #ddd;
		padding: 10px;
		border-radius: 6px;
	}

	.btn {
		background-color: #007AFF;
		color: white;
		margin-top: 20px;
		border-radius: 8px;
	}

	.btn-read {
		background-color: #fff;
		color: #007AFF;
		border: 1px solid #007AFF;
	}
</style>